#!/usr/bin/env bash
# Shared env for local group + txfees blacklist test
# Usage: source scripts/group-blacklist-local/env.sh

export HOME1="${HOME1:-${HOME}/.oraid/validator1}"
export HOME2="${HOME2:-${HOME}/.oraid/validator2}"
export CHAIN_ID="${CHAIN_ID:-testing}"
# use 127.0.0.1 (avoid macOS localhost -> ::1 issues)
export NODE="${NODE:-tcp://127.0.0.1:26657}"
export FROM="${FROM:-validator1}"
# Keys are regenerated by multinode-local-testnet.sh, so addresses are read from the keyring.
export ADMIN="$(oraid keys show "$FROM" -a --home "$HOME1" --keyring-backend test 2>/dev/null)"
export MEMBER2="$(oraid keys show validator2 -a --home "$HOME2" --keyring-backend test 2>/dev/null)"
export TARGET="$(oraid keys show "${USER}-eth" -a --home "$HOME1" --keyring-backend test 2>/dev/null)"
export GROUP_ID="1"
# Must equal x/txfees FoundationGroupPolicyAddress (first group policy created on a fresh chain).
export POLICY_ADDR="orai1afk9zr2hn2jsac63h4hm60vl9z3e5u69gndzf7c99cqge3vzwjzsp4a86q"
export DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
